import itertools
import random
from scipy.optimize import linear_sum_assignment
import numpy as np

def is_diverse(S, n):
    for c in [0, 1]:
        adj = np.zeros((n, len(S)), dtype=int)
        for j in range(n):
            for idx, f in enumerate(S):
                if f[j] == c:
                    adj[j, idx] = 1
        cost = 1 - adj
        row_ind, col_ind = linear_sum_assignment(cost)
        if cost[row_ind, col_ind].sum() == 0:
            return True
    return False

def find_M(n):
    all_flags = list(itertools.product([0, 1], repeat=n))
    # We want the largest m such that there exists a non-diverse set of size m.
    # Then M = m + 1.
    best_m = 0
    # We can't try all subsets, but we can try many random subsets.
    # For small n, we can try more.
    for m in range(1, 2**n + 1):
        found_non_diverse = False
        # Increase iterations as m increases?
        iterations = 2000
        for _ in range(iterations):
            S = random.sample(all_flags, m)
            if not is_diverse(S, n):
                found_non_diverse = True
                break
        if found_non_diverse:
            best_m = m
        else:
            # Since we might have missed it, we should be careful.
            # But for m small, we are likely to find it if it exists.
            # If we don't find a non-diverse set for m, it's likely we won't for m+1.
            # This is not strictly true, but we can stop here for a heuristic.
            break
    return best_m + 1

for n in range(2, 6):
    print(f"n={n}, M={find_M(n)}")

