    if len(S) < n:
        return False
    for c in [0, 1]:
        adj = np.zeros((n, len(S)), dtype=int)
        for j in range(n):
            for idx, f in enumerate(S):
                if f[j] == c:
                    adj[j, idx] = 1
        cost = 1 - adj
        row_ind, col_ind = linear_sum_assignment(cost)
        if len(row_ind) == n and cost[row_ind, col_ind].sum() == 0:
            return True
    return False

